mapper.select:
SELECT wr.*, w.name AS workflow_name, origin.recipe_key, v.version_number, v.definition_hash AS version_definition_hash, v.published_at AS version_published_at, wi.id AS intervention_id, wi.workflow_step_run_id AS intervention_step_run_id, isr.node_id AS intervention_step_node_id, wi.category AS intervention_category, wi.reason_code AS intervention_reason_code, wi.owner_user_id AS intervention_owner_user_id, wi.status AS intervention_status, wi.source_version AS intervention_source_version, wi.created_at AS intervention_created_at, wi.updated_at AS intervention_updated_at FROM workflow_run wr JOIN workflow w ON w.workspace_id = wr.workspace_id AND w.id = wr.workflow_id JOIN workflow_version v ON v.workspace_id = wr.workspace_id AND v.workflow_id = wr.workflow_id AND v.id = wr.workflow_version_id LEFT JOIN workflow_recipe_origin origin ON origin.workspace_id = wr.workspace_id AND origin.workflow_id = wr.workflow_id LEFT JOIN workflow_intervention wi ON wi.workspace_id = wr.workspace_id AND wi.workflow_run_id = wr.id AND wi.status = 'open' LEFT JOIN workflow_step_run isr ON isr.workspace_id = wi.workspace_id AND isr.workflow_run_id = wi.workflow_run_id AND isr.id = wi.workflow_step_run_id WHERE wr.workspace_id = #{workspaceId}
AND wr.status = #{status}
AND COALESCE(wi.category, CASE WHEN wr.failure_code IS NULL THEN NULL WHEN wr.failure_code IN ('actor_unavailable', 'actor_inactive') THEN 'actor' WHEN wr.failure_code IN ('permission_denied', 'action_permission_missing') THEN 'permission' WHEN wr.failure_code IN ('reference_unavailable', 'record_unavailable') THEN 'reference' WHEN wr.failure_code IN ('retry_exhausted', 'retry_not_safe') THEN 'retry' WHEN wr.failure_code = 'transient_database_failure' THEN 'retry' WHEN wr.failure_code IN ('configuration_invalid', 'invalid_action_config', 'definition_corrupt', 'definition_invalid') THEN 'configuration' ELSE 'execution' END) = #{failureCategory}
AND wi.owner_user_id = #{ownerId}
AND (wr.started_at < #{beforeStartedAt} OR (wr.started_at = #{beforeStartedAt} AND wr.id < #{beforeId}))
ORDER BY wr.started_at DESC, wr.id DESC LIMIT #{limit}

