mapper.update:
UPDATE workflow_invocation
SET status = 'confirmed', confirmation_key = #{confirmationKey},
    confirmed_at = #{confirmedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND requested_by_id = #{requestedById}
  AND status = 'prepared'
  AND expires_at >= #{confirmedAt}
  AND confirmation_key IS NULL

UPDATE workflow_invocation_record
SET workflow_run_id = #{workflowRunId}, execution_status = 'queued',
    execution_failure_category = NULL
WHERE workspace_id = #{workspaceId}
  AND invocation_id = #{invocationId}
  AND record_id = #{recordId}
  AND preview_status = 'ready'
  AND workflow_run_id IS NULL
  AND execution_status = 'pending'

UPDATE workflow_invocation_record
SET execution_status = 'skipped', execution_failure_category = #{category}
WHERE workspace_id = #{workspaceId}
  AND invocation_id = #{invocationId}
  AND record_id = #{recordId}
  AND execution_status = 'pending'

UPDATE workflow_invocation
SET status = #{status}, completed_at = #{completedAt}
WHERE workspace_id = #{workspaceId} AND id = #{id}

UPDATE workflow_invocation
SET status = #{status}, completed_at = #{completedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status IN ('confirmed', 'running')
  AND completed_at IS NULL

UPDATE workflow_invocation
SET status = 'running'
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status IN ('confirmed', 'running')

UPDATE workflow_invocation
SET status = 'cancelled', completed_at = #{completedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status IN ('prepared', 'confirmed', 'running')

UPDATE workflow_invocation_record
SET execution_status = 'cancelled', execution_failure_category = NULL
WHERE workspace_id = #{workspaceId}
  AND invocation_id = #{invocationId}
  AND workflow_run_id IS NULL
  AND execution_status = 'pending'

UPDATE workflow_intervention
SET owner_user_id = #{ownerUserId}, source_version = source_version + 1
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'open'
  AND source_version = #{expectedSourceVersion}

UPDATE workflow_intervention
SET status = #{status}, resolved_at = CURRENT_TIMESTAMP(6),
    source_version = source_version + 1
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'open'
  AND source_version = #{expectedSourceVersion}

UPDATE workflow_intervention
SET status = #{status}, resolved_at = CURRENT_TIMESTAMP(6),
    source_version = source_version + 1
WHERE workspace_id = #{workspaceId}
  AND workflow_run_id = #{workflowRunId}
  AND status = 'open'
